/* ── 常用图标别名 ── */
ICONS['open-link'] = ICONS.external;
ICONS['plus'] = ICONS.add;
ICONS['bell'] = ICONS.notification;

/* ── Icon Color System v2.0 ──
 * 三种颜色模式:
 *   auto  (默认): 所有路径统一使用 currentColor，跟随界面颜色
 *   fixed (指定): 所有路径统一使用声明的固定颜色
 *   brand (品牌): 品牌路径使用品牌渐变色 url(#cgo-brand-grad)，
 *                 其余路径使用 currentColor 适配界面
 */
const _BRAND_GRAD =
    '<linearGradient id="cgo-brand-grad" x1="0%" y1="100%" x2="0%" y2="0%"><stop offset="0%" stop-color="var(--brand-gradient-start-appname)"/><stop offset="100%" stop-color="var(--brand-gradient-end-appname)"/></linearGradient>';
const _BRAND_IDX = {
    addone: [0],
    baby: [2],
    "bar-chart": [0],
    bus: [1,2],
    calendar: [1,3,5],
    counter: [2,3],
    crh: [2],
    delete: [1],
    design: [0],
    download: [0],
    drunk: [1],
    edit: [0],
    elder: [2],
    elevator: [7,8],
    escalator: [1],
    "export-svg": [0],
    eye: [1],
    "horizontal-flip": [1],
    layer: [0],
    light: [1,2],
    link: [1],
    login: [0],
    logout: [0],
    luggage: [1],
    menu: [2],
    monorail: [0,1],
    noentry: [2],
    notification: [0],
    payment: [2,3,4],
    plugin: [4],
    police: [1],
    pregnant: [1],
    preset: [1],
    security: [2],
    sort: [2],
    sparkle: [0],
    speaker: [2],
    stairs: [0,1],
    stroller: [1,2],
    ticket: [1],
    time: [2],
    toilet: [2,3],
    train: [0,1],
    tram: [5],
    unlock: [0],
    "vertical-flip": [1],
    "vi-clss": [0],
    "vi-line": [0],
    "vi-nbr": [1],
    "vi-oth": [2,3,4],
    "vi-stn": [2],
    "vi-sub": [0],
    "vi-text": [0],
    "vi-way": [1],
    "view-list": [0,1],
    walk: [1],
    window: [2],
};
function _splitD(d) {
    const parts = d.match(/<(path|circle|rect|polygon|ellipse|line|polyline)[^>]*\/>/g);
    return parts || [d];
}
function _injectFill(el, fill) {
    return el.replace(/\/>$/, ' fill="' + fill + '"/>');
}

function esc(str) {
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/**
 * 构建完整 SVG 字符串。<cgo-icon> 与 CGO.icon 共享此函数，保证视觉一致。
 * @param {string} name
 * @param {{size?:number|string,class?:string,color?:string,colorMode?:string,title?:string,ariaHidden?:boolean}} [opts]
 * @returns {string}
 */
export function buildSvg(name, opts = {}) {
    const entry = ICONS[name];
    if (!entry) {
        console.warn('[CGO.icon] 未找到图标："' + name + '"');
        return '';
    }
    const size = opts.size !== undefined ? opts.size : 24;
    const sizeStr = typeof size === 'number' ? size + 'px' : size;
    const isStroke = entry.type === 'stroke';
    const cls = 'cgo-svg-icon' + (isStroke ? ' cgo-stroke-icon' : '') + (opts.class ? ' ' + opts.class : '');
    const ariaH = opts.ariaHidden !== false ? ' aria-hidden="true"' : '';
    const titleEl = opts.title ? '<title>' + esc(opts.title) + '</title>' : '';
    const colorMode = opts.colorMode || (opts.color ? 'fixed' : 'auto');
    const brandIdx = _BRAND_IDX[name] || [];
    const hasBrand = brandIdx.length > 0;

    /* ── Brand 模式：按路径索引分别着色 ── */
    if (colorMode === 'brand' && hasBrand) {
        let inner = titleEl + '<defs>' + _BRAND_GRAD + '</defs>';
        const paths = _splitD(entry.d);
        const unifiedFill = isStroke ? 'none' : 'var(--icon-clr, currentColor)';
        for (let i = 0; i < paths.length; i++) {
            const fill = brandIdx.includes(i) ? 'url(#cgo-brand-grad)' : unifiedFill;
            inner += _injectFill(paths[i], fill);
        }
        return (
            '<svg class="' +
            cls +
            '"' +
            ' xmlns="http://www.w3.org/2000/svg"' +
            ' viewBox="' +
            (entry.viewBox || '0 0 24 24') +
            '"' +
            ' width="' +
            sizeStr +
            '"' +
            ' height="' +
            sizeStr +
            '"' +
            (isStroke ? ' stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' : '') +
            ariaH +
            '>' +
            inner +
            '</svg>'
        );
    }

    /* ── Auto / Fixed / 无品牌索引 → 统一 fill ── */
    let fillAttr = isStroke ? 'none' : 'currentColor';
    if (opts.color) fillAttr = opts.color;
    return (
        '<svg class="' +
        cls +
        '"' +
        ' xmlns="http://www.w3.org/2000/svg"' +
        ' viewBox="' +
        (entry.viewBox || '0 0 24 24') +
        '"' +
        ' width="' +
        sizeStr +
        '"' +
        ' height="' +
        sizeStr +
        '"' +
        ' fill="' +
        fillAttr +
        '"' +
        (isStroke ? ' stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' : '') +
        ariaH +
        '>' +
        titleEl +
        entry.d +
        '</svg>'
    );
}

export function iconNames() {
    return Object.keys(ICONS);
}

export { esc as _escIcon };
